-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 13 recettes, 1 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"tutu-a-mineira","country":"BR","place":"br-minas-gerais","original":"Tutu à mineira","title":"Tutu à mineira (purée de haricots noirs, couve et linguiça)","en":"Tutu à mineira (Minas bean mash)","es":"Tutu à mineira (puré de frijoles de Minas)","desc":"Haricots noirs cuits puis écrasés et épaissis à la farine de manioc avec lard et oignon, servis avec chou kale sauté à l’ail, saucisse linguiça, couenne croustillante, riz et œuf : le plat de Minas Gerais.","cat":"Plat principal","diff":"medium","prep":30,"cook":120,"serv":6,"reference":"https://en.wikipedia.org/wiki/Tutu_(food)","ing":[["Haricots noirs",500,"g","trempés une nuit"],["Lard fumé",150,"g","en dés"],["Oignon",1,null,"haché"],["Ail",4,"gousses","hachées"],["Farine de manioc",150,"g",null],["Linguiça (saucisse fumée)",400,"g","en rondelles"],["Chou kale (couve)",1,"botte","en fines lanières"],["Œufs",6,null,"durs ou au plat"],["Riz blanc cuit",600,"g",null],["Huile",3,"c. à soupe",null],["Laurier",2,"feuilles",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Cuire les haricots avec le laurier 1 h 30 jusqu’à ce qu’ils soient fondants, puis les mixer grossièrement avec un peu de leur jus.","Dorer le lard, ajouter oignon et la moitié de l’ail, puis la purée de haricots.","Verser la farine de manioc en pluie en remuant jusqu’à une purée épaisse et lisse, saler et poivrer.","Poêler la linguiça.","Sauter rapidement le chou à l’huile avec le reste de l’ail.","Servir le tutu avec la linguiça, le chou, les œufs et le riz."],"photo":{"file":"File:Tutu à Mineira (7080706387).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Tutu_%C3%A0_Mineira_%287080706387%29.jpg/1280px-Tutu_%C3%A0_Mineira_%287080706387%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Tutu_%C3%A0_Mineira_(7080706387).jpg","author":"Emerson Pardo","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"cuscuz-paulista","country":"BR","place":"br-sao-paulo","original":"Cuscuz paulista","title":"Cuscuz paulista (couronne de semoule de maïs aux légumes, sardines et œufs)","en":"Cuscuz paulista (São Paulo corn couscous)","es":"Cuscuz paulista (cuscús de maíz de São Paulo)","desc":"Farine de maïs cuite dans un bouillon de tomates, petits pois, maïs, olives et sardines ou poulet, tassée dans un moule à savarin décoré de rondelles d’œuf dur et de tomate, servie froide ou tiède.","cat":"Plat principal","diff":"medium","prep":30,"cook":25,"serv":8,"reference":"https://en.wikipedia.org/wiki/Cuscuz","ing":[["Farine de maïs grossière (flocão)",300,"g",null],["Farine de manioc",100,"g",null],["Tomates",4,null,"dont 2 en rondelles pour décorer"],["Oignon",1,null,"haché"],["Ail",3,"gousses",null],["Sardines à l’huile",2,"boîtes",null],["Petits pois et maïs",200,"g",null],["Olives vertes",80,"g","tranchées"],["Cœurs de palmier",150,"g","en rondelles"],["Œufs durs",4,null,"en rondelles"],["Persil et ciboule",3,"c. à soupe","hachés"],["Bouillon",700,"ml",null],["Huile d’olive",4,"c. à soupe",null],["Sel",1,"c. à thé",null]],"steps":["Tapisser un moule à savarin huilé de rondelles d’œuf, de tomate et de quelques sardines.","Faire revenir oignon et ail dans l’huile, ajouter 2 tomates hachées et cuire 5 minutes.","Ajouter bouillon, petits pois, maïs, olives, cœurs de palmier et le reste des sardines émiettées, porter à ébullition.","Verser les farines en pluie en remuant jusqu’à ce que le mélange se détache des parois, ajouter les herbes.","Tasser dans le moule en pressant bien et laisser reposer 20 minutes.","Démouler sur un plat et servir en tranches."],"photo":{"file":"File:Cuscuz paulista.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/02/Cuscuz_paulista.jpg","page":"https://commons.wikimedia.org/wiki/File:Cuscuz_paulista.jpg","author":"Everton137","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"tamal-tolimense","country":"CO","place":"co-tolima","original":"Tamal tolimense","title":"Tamal tolimense (tamal de maïs au porc, poulet et œuf en feuille de bananier)","en":"Tolima tamale","es":"Tamal tolimense","desc":"Grand tamal de pâte de maïs et de riz garni de porc, de poulet, de lard, d’œuf dur, de pois et de pomme de terre, enveloppé dans des feuilles de bananier ficelées et cuit longuement à la vapeur, le petit-déjeuner dominical du Tolima.","cat":"Plat principal","diff":"hard","prep":90,"cook":240,"serv":8,"reference":"https://es.wikipedia.org/wiki/Tamal_tolimense","ing":[["Farine de maïs précuite (ou masa)",500,"g",null],["Riz",150,"g","cuit à moitié"],["Échine de porc",500,"g","en morceaux"],["Poulet",500,"g","en morceaux"],["Lard ou poitrine",250,"g","en tranches"],["Œufs durs",4,null,"coupés en deux"],["Pois jaunes ou petits pois",200,"g","cuits"],["Pommes de terre",3,null,"en rondelles"],["Carottes",2,null,"en rondelles"],["Hogao (tomate, oignon, ciboule)",1,"tasse",null],["Cumin et achiote",1,"c. à thé",null],["Feuilles de bananier",16,null,"passées à la flamme"],["Bouillon",500,"ml",null],["Sel",2,"c. à thé",null]],"steps":["Mariner porc et poulet avec hogao, cumin, achiote et sel au moins 2 heures.","Pétrir la farine de maïs avec le bouillon chaud, un peu d’hogao et le riz en une pâte souple.","Croiser deux feuilles de bananier, étaler une couche de pâte au centre.","Disposer porc, poulet, lard, œuf, pois, pomme de terre et carotte, couvrir d’une cuillerée de pâte.","Refermer les feuilles en paquet carré et ficeler solidement.","Cuire 4 heures dans une grande marmite d’eau frémissante ou à la vapeur, et servir avec du pain et du chocolat chaud."],"photo":{"file":"File:Tamal tolimense abierto.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Tamal_tolimense_abierto.jpg/1280px-Tamal_tolimense_abierto.jpg","page":"https://commons.wikimedia.org/wiki/File:Tamal_tolimense_abierto.jpg","author":"JOAN","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"papeda-kuah-kuning","country":"ID","place":{"slug":"id-maluku","name":"Moluques","type":"region","lat":-3.24,"lng":130.14,"summary":"Archipel des épices de l’est indonésien, où le sagou remplace le riz : papeda, poisson au curcuma, clou de girofle et muscade."},"original":"Papeda","title":"Papeda et ikan kuah kuning (gelée de sagou et poisson au curcuma)","en":"Papeda with yellow fish soup","es":"Papeda con sopa amarilla de pescado","desc":"Gelée de sagou translucide et élastique, enroulée sur des baguettes et servie avec un bouillon de poisson parfumé au curcuma, à la citronnelle et au citron vert : l’aliment de base des Moluques et de la Papouasie.","cat":"Plat principal","diff":"medium","prep":30,"cook":40,"serv":4,"reference":"https://en.wikipedia.org/wiki/Papeda_(food)","ing":[["Fécule de sagou",250,"g",null],["Eau",1.2,"l","dont 1 l bouillante"],["Citron vert",2,null,null],["Poisson à chair ferme (thon, maquereau)",800,"g","en tranches"],["Curcuma frais",30,"g",null],["Échalotes",6,null,null],["Ail",4,"gousses",null],["Piments rouges",3,null,null],["Noix de bancoul (kemiri)",3,null,null],["Citronnelle",2,"tiges","écrasées"],["Feuilles de combava",4,null,null],["Basilic citron",1,"poignée",null],["Tomates",2,null,"en quartiers"],["Sel",1.5,"c. à thé",null]],"steps":["Frotter le poisson de citron vert et de sel et laisser reposer 15 minutes.","Mixer curcuma, échalotes, ail, piments et kemiri en pâte et la faire revenir dans un peu d’huile 5 minutes.","Ajouter citronnelle, combava et 1 litre d’eau, porter à ébullition puis pocher le poisson 10 minutes avec les tomates et le basilic.","Délayer le sagou dans 200 ml d’eau froide jusqu’à ce qu’il soit lisse.","Verser l’eau bouillante d’un coup en remuant vigoureusement jusqu’à ce que le mélange devienne translucide et gélatineux.","Enrouler la papeda sur deux baguettes, la déposer dans des bols et la napper du bouillon de poisson."],"photo":{"file":"File:Papeda, Kuah Kuning, Ikan Tude Bakar 1.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Papeda%2C_Kuah_Kuning%2C_Ikan_Tude_Bakar_1.jpg/1280px-Papeda%2C_Kuah_Kuning%2C_Ikan_Tude_Bakar_1.jpg","page":"https://commons.wikimedia.org/wiki/File:Papeda,_Kuah_Kuning,_Ikan_Tude_Bakar_1.jpg","author":"Gunawan Kartapranata","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"sate-lilit-bali","country":"ID","place":"id-bali","original":"Sate lilit","title":"Sate lilit (brochettes de porc haché à la citronnelle de Bali)","en":"Balinese pork sate lilit","es":"Sate lilit balinés de cerdo","desc":"Porc haché mêlé de noix de coco râpée, de lait de coco et de pâte d’épices basa genep, modelé autour de tiges de citronnelle puis grillé sur la braise, un incontournable des cérémonies balinaises.","cat":"Plat principal","diff":"medium","prep":40,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Sate_lilit","ing":[["Porc haché (échine)",500,"g",null],["Noix de coco râpée",100,"g",null],["Lait de coco épais",3,"c. à soupe",null],["Échalotes",6,null,null],["Ail",4,"gousses",null],["Gingembre, galanga, curcuma frais",30,"g","en tout"],["Piments rouges",3,null,null],["Noix de bancoul (kemiri)",3,null,null],["Pâte de crevette (terasi)",1,"c. à thé",null],["Sucre de palme",1,"c. à soupe",null],["Feuilles de combava",4,null,"ciselées finement"],["Tiges de citronnelle",16,null,"servant de bâtonnets"],["Sel",1,"c. à thé",null]],"steps":["Piler ou mixer échalotes, ail, gingembre, galanga, curcuma, piments, kemiri et terasi, puis cuire cette pâte 5 minutes à la poêle.","La laisser refroidir et la mélanger au porc haché, à la coco râpée, au lait de coco, au sucre de palme, au combava et au sel.","Pétrir jusqu’à ce que la farce soit collante.","Mouler une poignée de farce autour du bas de chaque tige de citronnelle en la pressant.","Griller 8 à 10 minutes sur des braises en tournant jusqu’à ce qu’elles soient dorées.","Servir avec du riz, des haricots longs sautés et un sambal matah."],"photo":{"file":"File:Pork Sate Lilit Bali 1.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Pork_Sate_Lilit_Bali_1.JPG/1280px-Pork_Sate_Lilit_Bali_1.JPG","page":"https://commons.wikimedia.org/wiki/File:Pork_Sate_Lilit_Bali_1.JPG","author":"Gunawan Kartapranata","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"gorditas-de-chicharron","country":"MX","original":"Gorditas de chicharrón","title":"Gorditas de chicharrón prensado (galettes de maïs farcies)","en":"Gorditas with pressed pork crackling","es":"Gorditas de chicharrón prensado","desc":"Épaisses galettes de masa cuites au comal puis ouvertes en poche et garnies de chicharrón prensado mijoté en salsa, de fromage, de laitue, de tomate et de crème, un antojito de rue du centre du Mexique.","cat":"Street food","diff":"medium","prep":30,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Gordita","ing":[["Masa harina",400,"g",null],["Eau tiède",300,"ml","environ"],["Saindoux",2,"c. à soupe",null],["Chicharrón prensado",300,"g",null],["Salsa verde ou roja",250,"ml",null],["Queso fresco",120,"g","émietté"],["Laitue",0.25,null,"émincée"],["Tomate",1,null,"en dés"],["Crème (crema)",100,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Pétrir masa harina, eau, saindoux et sel en pâte souple et la diviser en 8 boules.","Mijoter le chicharrón prensado avec la salsa 10 minutes jusqu’à ce qu’il soit tendre.","Aplatir les boules en galettes épaisses de 1 cm.","Les cuire 4 minutes par face sur un comal chaud jusqu’à ce qu’elles gonflent légèrement.","Les fendre sur le côté pour former une poche.","Garnir de chicharrón, fromage, laitue, tomate et crème, et servir aussitôt."],"photo":{"file":"File:Gordita.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Gordita.jpg/1280px-Gordita.jpg","page":"https://commons.wikimedia.org/wiki/File:Gordita.jpg","author":"Paul Goyette from Chicago, Illinois, USA","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"huarache-de-nopal","country":"MX","place":"mx-ciudad-de-mexico","original":"Huarache","title":"Huarache aux nopales et bœuf (galette de maïs en forme de sandale)","en":"Mexico City huarache","es":"Huarache de nopales y bistec","desc":"Longue galette ovale de masa fourrée de haricots, cuite au comal puis tartinée de salsa et garnie de nopales grillés, de bistec haché, d’oignon et de fromage, la spécialité née à Mexico près du canal de La Viga.","cat":"Street food","diff":"medium","prep":30,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Huarache_(food)","ing":[["Masa harina",400,"g",null],["Eau tiède",300,"ml",null],["Haricots refrits",200,"g",null],["Nopales",4,null,"nettoyés, en lanières"],["Bifteck fin",300,"g","en petits morceaux"],["Salsa verde",200,"ml",null],["Oignon blanc",1,null,"émincé"],["Queso fresco",100,"g","émietté"],["Laitue",0.25,null,"émincée"],["Huile ou saindoux",3,"c. à soupe",null],["Sel",1,"c. à thé",null]],"steps":["Pétrir masa harina et eau salée en pâte souple.","Façonner un long boudin, y loger une ligne de haricots refrits, refermer puis aplatir en ovale de 25 cm.","Cuire 3 à 4 minutes par face sur un comal, puis le dorer légèrement dans un peu de saindoux.","Griller les nopales salés et saisir le bifteck avec l’oignon.","Napper le huarache de salsa, puis garnir de nopales, de viande, de laitue et de fromage.","Servir chaud."],"photo":{"file":"File:Huarache nopal.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/c/c9/Huarache_nopal.jpg","page":"https://commons.wikimedia.org/wiki/File:Huarache_nopal.jpg","author":"Brenda lopez lee","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"panuchos-yucatecos","country":"MX","place":"mx-yucatan","original":"Panuchos","title":"Panuchos yucatèques (tortillas frites farcies de haricots noirs)","en":"Yucatán panuchos","es":"Panuchos yucatecos","desc":"Petites tortillas gonflées, fendues et farcies de purée de haricots noirs, frites puis garnies de dinde ou de cochinita effilochée, d’oignon rouge mariné, de tomate, d’avocat et de laitue.","cat":"Street food","diff":"medium","prep":40,"cook":30,"serv":4,"reference":"https://en.wikipedia.org/wiki/Panucho","ing":[["Masa harina",300,"g",null],["Eau tiède",230,"ml",null],["Haricots noirs refrits",200,"g",null],["Dinde ou poulet effiloché",300,"g","cuit à l’achiote"],["Oignon rouge",1,null,"émincé"],["Jus d’orange amère (ou citron vert)",100,"ml",null],["Piment habanero",1,null,"émincé"],["Tomate",1,null,"en rondelles"],["Avocat",1,null,"en tranches"],["Laitue",0.25,null,"émincée"],["Huile de friture",300,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Mariner l’oignon rouge avec le jus d’orange amère, le habanero et le sel au moins 1 heure.","Former de petites tortillas de 12 cm et les cuire sur un comal chaud jusqu’à ce qu’elles gonflent.","Inciser le bord de chaque tortilla gonflée pour ouvrir la poche et y étaler une fine couche de haricots noirs.","Frire les tortillas farcies dans l’huile chaude jusqu’à ce qu’elles soient dorées et croustillantes.","Garnir de dinde effilochée, laitue, tomate, avocat et oignon mariné.","Servir avec une salsa au habanero."],"photo":{"file":"File:Panucho yucateco.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Panucho_yucateco.jpg/1280px-Panucho_yucateco.jpg","page":"https://commons.wikimedia.org/wiki/File:Panucho_yucateco.jpg","author":"Padaguan","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"salbutes-yucatecos","country":"MX","place":"mx-yucatan","original":"Salbutes","title":"Salbutes yucatèques (tortillas soufflées frites à la dinde)","en":"Yucatán salbutes","es":"Salbutes yucatecos","desc":"Petites tortillas de maïs frites jusqu’à ce qu’elles gonflent, moelleuses et légèrement croustillantes, garnies de dinde effilochée, laitue, tomate, avocat et oignon rouge mariné à l’orange amère.","cat":"Street food","diff":"easy","prep":30,"cook":25,"serv":4,"reference":"https://en.wikipedia.org/wiki/Salbute","ing":[["Masa harina",300,"g",null],["Farine de blé",2,"c. à soupe",null],["Levure chimique",0.5,"c. à thé",null],["Eau tiède",230,"ml",null],["Dinde effilochée",300,"g","cuite au recado rojo"],["Oignon rouge",1,null,"émincé"],["Jus d’orange amère",100,"ml",null],["Tomate",1,null,"en rondelles"],["Avocat",1,null,"en tranches"],["Concombre",0.5,null,"en rondelles"],["Laitue",0.25,null,"émincée"],["Huile de friture",400,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Mariner l’oignon rouge dans le jus d’orange amère salé.","Pétrir masa harina, farine, levure, sel et eau en pâte souple.","Aplatir des disques de 10 cm.","Les plonger directement dans l’huile chaude : ils gonflent en 1 à 2 minutes, les retourner et les égoutter.","Garnir de laitue, dinde, tomate, concombre, avocat et oignon mariné.","Servir immédiatement avec un peu de salsa au habanero."],"photo":{"file":"File:Salbutes, Restaurante Kinich, Izamal, Yucatan, Mexico.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Salbutes%2C_Restaurante_Kinich%2C_Izamal%2C_Yucatan%2C_Mexico.jpg/1280px-Salbutes%2C_Restaurante_Kinich%2C_Izamal%2C_Yucatan%2C_Mexico.jpg","page":"https://commons.wikimedia.org/wiki/File:Salbutes,_Restaurante_Kinich,_Izamal,_Yucatan,_Mexico.jpg","author":"Sharon Hahn Darlin","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"ofada-rice-stew","country":"NG","place":"ng-south-west","original":"Ofada rice and stew","title":"Riz ofada et sauce ayamase (ragoût de poivrons verts au locust bean)","en":"Ofada rice with ayamase stew","es":"Arroz ofada con guiso ayamase","desc":"Riz local non poli du pays yoruba servi dans des feuilles d’uma, avec un ragoût de poivrons et piments, d’huile de palme blanchie, de locust bean fermenté, de tripes, de viandes et d’œufs.","cat":"Plat principal","diff":"hard","prep":40,"cook":90,"serv":6,"reference":"https://en.wikipedia.org/wiki/Ofada_rice","ing":[["Riz ofada",600,"g","lavé plusieurs fois"],["Poivrons verts",6,null,null],["Piments scotch bonnet",4,null,null],["Oignons",2,null,null],["Huile de palme",250,"ml",null],["Iru (locust bean fermenté)",3,"c. à soupe",null],["Bœuf et tripes (shaki)",800,"g","cuits, en morceaux"],["Œufs durs",6,null,null],["Écrevisses séchées moulues",2,"c. à soupe",null],["Cubes de bouillon",2,null,null],["Sel",1,"c. à thé",null],["Feuilles d’uma ou de bananier",6,null,"pour servir"]],"steps":["Cuire le riz ofada à l’eau salée environ 40 minutes jusqu’à tendreté, en égouttant à mi-cuisson.","Mixer grossièrement poivrons, piments et un oignon, puis faire réduire la purée à sec dans une casserole.","Chauffer l’huile de palme à couvert jusqu’à ce qu’elle blanchisse (fenêtre ouverte), la laisser tiédir, puis y faire revenir l’autre oignon et l’iru.","Ajouter la purée de poivrons et frire 20 minutes en remuant.","Incorporer viandes, tripes, écrevisses et bouillon, mijoter 15 minutes puis ajouter les œufs.","Servir le riz sur des feuilles d’uma avec la sauce."],"photo":{"file":"File:OfadaRice with assorted meat and egg.png","url":"https://upload.wikimedia.org/wikipedia/commons/a/ab/OfadaRice_with_assorted_meat_and_egg.png","page":"https://commons.wikimedia.org/wiki/File:OfadaRice_with_assorted_meat_and_egg.png","author":"Jostbrain","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"pounded-yam-egusi","country":"NG","place":"ng-south-west","original":"Iyan","title":"Pounded yam et soupe egusi (purée d’igname et sauce aux graines de courge)","en":"Pounded yam with egusi soup","es":"Ñame machacado con sopa egusi","desc":"Igname cuite pilée jusqu’à une pâte lisse et élastique, servie avec une soupe épaisse de graines de melon moulues, d’huile de palme, de feuilles vertes, de viande et de poisson fumé, que l’on mange avec la main.","cat":"Plat principal","diff":"medium","prep":30,"cook":75,"serv":6,"reference":"https://en.wikipedia.org/wiki/Pounded_yam","ing":[["Igname blanche (pona)",1.5,"kg","pelée, en morceaux"],["Graines d’egusi moulues",250,"g",null],["Huile de palme",150,"ml",null],["Oignon",1,null,"haché"],["Piments scotch bonnet",2,null,"mixés"],["Bœuf",600,"g","en morceaux, précuit"],["Poisson fumé",200,"g","émietté"],["Écrevisses séchées moulues",2,"c. à soupe",null],["Iru (locust bean)",1,"c. à soupe",null],["Épinards ou feuilles amères",300,"g","hachés"],["Cubes de bouillon",2,null,null],["Bouillon de viande",500,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Cuire l’igname à l’eau 20 minutes jusqu’à ce qu’elle soit très tendre.","La piler au mortier encore chaude, en ajoutant un peu d’eau de cuisson, jusqu’à une pâte lisse, élastique et sans grumeaux.","Délayer l’egusi avec un peu d’eau et d’oignon en pâte épaisse.","Chauffer l’huile de palme, y faire revenir l’iru et le piment, puis ajouter l’egusi par cuillerées et cuire 10 minutes pour former des grumeaux.","Ajouter bouillon, viande, poisson fumé, écrevisses et assaisonnement, mijoter 15 minutes puis ajouter les feuilles 5 minutes.","Façonner le pounded yam en boules et servir avec la soupe."],"photo":{"file":"File:Pounded Yam and Egusi Soup.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Pounded_Yam_and_Egusi_Soup.jpg/1280px-Pounded_Yam_and_Egusi_Soup.jpg","page":"https://commons.wikimedia.org/wiki/File:Pounded_Yam_and_Egusi_Soup.jpg","author":"Justdifference","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"cuy-chactado-arequipa","country":"PE","place":"pe-arequipa","original":"Cuy chactado","title":"Cuy chactado d’Arequipa (cochon d’Inde frit sous une pierre)","en":"Arequipa cuy chactado (pressed fried guinea pig)","es":"Cuy chactado arequipeño","desc":"Cochon d’Inde ouvert à plat, assaisonné d’ail et de cumin, fariné de maïs et frit sous le poids d’une pierre plate jusqu’à ce que la peau soit très croustillante, servi avec pommes de terre, maïs et fèves.","cat":"Plat principal","diff":"hard","prep":30,"cook":30,"serv":2,"reference":"https://es.wikipedia.org/wiki/Cuy_chactado","ing":[["Cochon d’Inde (cuy) préparé, ouvert",1,null,"environ 800 g"],["Ail",4,"gousses","écrasées"],["Cumin moulu",1,"c. à thé",null],["Jus de citron vert",2,"c. à soupe",null],["Farine de maïs",100,"g",null],["Huile de friture",500,"ml",null],["Pommes de terre",4,null,"cuites"],["Épis de maïs choclo",2,null,"cuits"],["Fèves cuites",150,"g",null],["Sarsa criolla (oignon rouge, citron, piment)",1,"tasse",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Frotter le cuy d’ail, de cumin, de citron, de sel et de poivre et laisser mariner 2 heures.","L’essuyer puis le fariner de maïs des deux côtés.","Chauffer l’huile dans une grande poêle profonde et y déposer le cuy à plat, peau vers le bas.","Le couvrir d’une pierre plate propre ou d’un poids pour qu’il reste parfaitement plat.","Frire 12 à 15 minutes par face jusqu’à ce que la peau soit dorée et croustillante.","Servir entier avec pommes de terre, maïs, fèves et sarsa criolla."],"photo":{"file":"File:Cuy chactao.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/81/Cuy_chactao.jpg","page":"https://commons.wikimedia.org/wiki/File:Cuy_chactao.jpg","author":"Jorge Gobbi","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"kaeng-hang-le","country":"TH","place":"th-chiang-mai-region","original":"Kaeng hang le","title":"Kaeng hang le (curry de porc birman du nord de la Thaïlande)","en":"Northern Thai hang lay pork curry","es":"Kaeng hang le (curry de cerdo del norte de Tailandia)","desc":"Curry sans lait de coco, d’influence birmane, où la poitrine de porc mijote longuement avec une pâte de piments séchés, du gingembre en julienne, du tamarin, du sucre de palme et de l’ail mariné, spécialité de Chiang Mai.","cat":"Plat principal","diff":"medium","prep":30,"cook":120,"serv":6,"reference":"https://en.wikipedia.org/wiki/Kaeng_hang_le","ing":[["Poitrine et échine de porc",1,"kg","en gros cubes"],["Piments rouges secs",8,null,"trempés"],["Échalotes",6,null,null],["Ail",6,"gousses",null],["Citronnelle",2,"tiges",null],["Galanga",20,"g",null],["Pâte de crevette",1,"c. à thé",null],["Poudre de hang le (ou curry doux)",2,"c. à soupe",null],["Gingembre",60,"g","en fine julienne"],["Pulpe de tamarin",3,"c. à soupe",null],["Sucre de palme",3,"c. à soupe",null],["Sauce soja sucrée",1,"c. à soupe",null],["Ail mariné thaï",1,"tête",null],["Cacahuètes grillées",50,"g",null],["Sauce poisson",2,"c. à soupe",null]],"steps":["Piler piments, échalotes, ail, citronnelle, galanga et pâte de crevette en pâte de curry.","Mélanger le porc avec la pâte, la poudre de hang le et la sauce soja sucrée et laisser mariner 1 heure.","Faire revenir le porc mariné à sec jusqu’à ce qu’il soit bien saisi.","Couvrir d’eau, ajouter tamarin et sucre de palme et mijoter 1 h 30 à couvert jusqu’à ce que la viande soit fondante.","Ajouter le gingembre, l’ail mariné et les cacahuètes, et mijoter encore 15 minutes à découvert.","Rectifier avec la sauce poisson et servir avec du riz gluant."],"photo":{"file":"File:แกงฮังเล ที่ หลู้ลำ.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/%E0%B9%81%E0%B8%81%E0%B8%87%E0%B8%AE%E0%B8%B1%E0%B8%87%E0%B9%80%E0%B8%A5_%E0%B8%97%E0%B8%B5%E0%B9%88_%E0%B8%AB%E0%B8%A5%E0%B8%B9%E0%B9%89%E0%B8%A5%E0%B8%B3.jpg/1280px-%E0%B9%81%E0%B8%81%E0%B8%87%E0%B8%AE%E0%B8%B1%E0%B8%87%E0%B9%80%E0%B8%A5_%E0%B8%97%E0%B8%B5%E0%B9%88_%E0%B8%AB%E0%B8%A5%E0%B8%B9%E0%B9%89%E0%B8%A5%E0%B8%B3.jpg","page":"https://commons.wikimedia.org/wiki/File:%E0%B9%81%E0%B8%81%E0%B8%87%E0%B8%AE%E0%B8%B1%E0%B8%87%E0%B9%80%E0%B8%A5_%E0%B8%97%E0%B8%B5%E0%B9%88_%E0%B8%AB%E0%B8%A5%E0%B8%B9%E0%B9%89%E0%B8%A5%E0%B8%B3.jpg","author":"Chainwit.","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}}]$batch$::jsonb);
